private String createGaugeGraphiteMessage(MetricResult<GaugeResult> gauge,boolean committedValue){
  String metricMessage;
  if (committedValue) {
    metricMessage=String.format(Locale.US,"%s %s %s\n",createNormalizedMetricName(gauge,"gauge","value",CommittedOrAttemped.COMMITTED),gauge.getCommitted().getValue(),gauge.getCommitted().getTimestamp().getMillis() / 1000L);
  }
 else {
    metricMessage=String.format(Locale.US,"%s %s %s\n",createNormalizedMetricName(gauge,"gauge","value",CommittedOrAttemped.ATTEMPED),gauge.getAttempted().getValue(),gauge.getAttempted().getTimestamp().getMillis() / 1000L);
  }
  return metricMessage;
}
